const https = require("https");
const fs = require("fs");
const version = "{{MC_VERSION}}";

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  const buildsRes = await get(`https://api.purpurmc.org/v2/purpur/${version}`);
  if (buildsRes.status !== 200) throw new Error(`Purpur API returned ${buildsRes.status} for ${version}`);
  const data = JSON.parse(buildsRes.body.toString("utf8"));
  const build = data.builds.latest;
  console.log(`Downloading Purpur ${version} build ${build}`);
  const jar = await get(`https://api.purpurmc.org/v2/purpur/${version}/${build}/download`);
  if (jar.status !== 200) throw new Error(`Purpur download returned ${jar.status}`);
  fs.writeFileSync("server.jar", jar.body);
  console.log(`Saved server.jar (${(jar.body.length / 1024 / 1024).toFixed(1)} MB)`);
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
